public static Element[][] sampleUniformTransformation(Field field, int n) {
    Element[][] matrix = new Element[n][n];
    for (int i = 0; i  n; i++) {
        for (int j = 0; j  n; j++) {
            matrix[i][j] = field.newRandomElement();
        }
    }
    return matrix;
}

