        throw new IllegalArgumentException("The dimention of the matrix is incorrect. It's smaller than 2");
    }
    System.out.println("\nMatrix:");
    for (int i = 0; i  length; i++) {
        for (int j = 0; j  length; j++) {
            System.out.print(matrix[i][j] + "\t");
        }
        System.out.println();
    }
}

