    int size = matriz.length;
    double[][] nova = new double[size][size];
    for (int i = 0; i  size; i++) {
        for (int j = 0; j  size; j++) {
            nova[i][j] = getCofator(matriz, i, j);
        }
    }
    return getTransposta(nova);
}

