public static double[][] doubleClone(float[][] matrix) {
    int nr = matrix.length;
    int nc = matrix[0].length;
    double[][] cmatrix = new double[nr][nc];
    for (int r = 0; r  nr; r++) {
        for (int c = 0; c  nc; c++) {
            cmatrix[r][c] = matrix[r][c];
