    int lines = M.length;
    int columns = M[0].length;
    float[][] cM = new float[lines][columns];
    for (int i = 0; i  lines; i++) {
        for (int j = 0; j  columns; j++) {
            cM[i][j] = M[i][j];
        }
    }
    return cM;
}

