    PaceMatrix X = new PaceMatrix(m, n);
    double[][] C = X.getArray();
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            C[i][j] = A[i][j];
        }
    }
    return (Object) X;
}

public static int[][] reversalXandY(final int[][] array) {
    int col = array[0].length;
    int row = array.length;
    int[][] result = new int[col][row];
    for (int y = 0; y  col; y++) {
        for (int x = 0; x  row; x++) {
            result[x][y] = array[y][x];
        }
    }
    return result;
}

public static Matrix randomNormal(int m, int n) {
    Random random = new Random();
    Matrix A = new Matrix(m, n);
    double[][] X = A.getArray();
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            X[i][j] = random.nextGaussian();
        }
    }
    return A;
}

public static int[][] reversalXandY(final int[][] array) {
    int col = array[0].length;
    int row = array.length;
    int[][] result = new int[col][row];
    for (int y = 0; y  col; y++) {
        for (int x = 0; x  row; x++) {
            result[x][y] = array[y][x];
        }
    }
    return result;
}

public static void printMatrix(double[][] matrix) {
    if (matrix == null) {
        throw new IllegalArgumentException("Incorrect input, the matrix is null-pointed");
    }
    int length = matrix.length;
    if (length  2) {
        throw new IllegalArgumentException("The dimention of the matrix is incorrect. It's smaller than 2");
    }
    System.out.println("\nMatrix:");
    for (int i = 0; i  length; i++) {
        for (int j = 0; j  length; j++) {
            System.out.print(matrix[i][j] + "\t");
        }
        System.out.println();
    }
}

