public static Matrix randomNormal(int m, int n) {
    Random random = new Random();
    Matrix A = new Matrix(m, n);
    double[][] X = A.getArray();
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            X[i][j] = random.nextGaussian();
        }
    }
    return A;
}

