public static void printMatrix(double[][] matrix) {
    if (matrix == null) {
        throw new IllegalArgumentException("Incorrect input, the matrix is null-pointed");
    }
    int length = matrix.length;
    if (length  2) {
        throw new IllegalArgumentException("The dimention of the matrix is incorrect. It's smaller than 2");
    }
    System.out.println("\nMatrix:");
    for (int i = 0; i  length; i++) {
        for (int j = 0; j  length; j++) {
            System.out.print(matrix[i][j] + "\t");
        }
        System.out.println();
    }
}

protected double[][] getAdjunta(double[][] matriz) {
    int size = matriz.length;
    double[][] nova = new double[size][size];
    for (int i = 0; i  size; i++) {
        for (int j = 0; j  size; j++) {
            nova[i][j] = getCofator(matriz, i, j);
        }
    }
    return getTransposta(nova);
}

public static double[][] doubleClone(float[][] matrix) {
    int nr = matrix.length;
    int nc = matrix[0].length;
    double[][] cmatrix = new double[nr][nc];
    for (int r = 0; r  nr; r++) {
        for (int c = 0; c  nc; c++) {
            cmatrix[r][c] = matrix[r][c];
        }
    }
    return cmatrix;
}

protected double[][] getAdjunta(double[][] matriz) {
    int size = matriz.length;
    double[][] nova = new double[size][size];
    for (int i = 0; i  size; i++) {
        for (int j = 0; j  size; j++) {
            nova[i][j] = getCofator(matriz, i, j);
        }
    }
    return getTransposta(nova);
}

public static float[][] floatClone(double[][] matrix) {
    int nr = matrix.length;
    int nc = matrix[0].length;
    float[][] cmatrix = new float[nr][nc];
    for (int r = 0; r  nr; r++) {
        for (int c = 0; c  nc; c++) {
            cmatrix[r][c] = (float) matrix[r][c];
        }
    }
    return cmatrix;
}
